// Display corresponding numbers based on emotions
export const getNumberByString = (str: any): number => {
    const map: { [key: string]: number } = {
        'POSITIVE': 1,
        'NEUTRAL': 2,
        'NEGATIVE': 3
    };
    const upperStr = str.toLocaleUpperCase();
    return map[upperStr]  || 1;
}

// Find the corresponding emotion based on the numbers
export const getStringByNumber = (num: any, type: string = 'None'): string => {
   const map: { [key: number]: string } = {
        1: 'Positive',
        2: 'Neutral',
        3: 'Negative'
    };
    return map[Number(num)] || type;
}

export const getStringAccuracy = (num: number | undefined): string => {  
     const map: { [key: number]: string } = {
        0: 'Accurate',
        2: 'Inaccurate'
    };
    return map[Number(num)] || 'Inaccurate';
}

//  1_1  Emotionally Types_Acceptations_Whether to purchase a card or not 
export const getNumberByString_ = (str: string, index: number): number | undefined => {
    if (str) {
        const arr = str.split('_');
        if (arr.length >= 2) {
            return parseInt(arr[index]);
        } else {
            return getNumberByString(str)
        }
    }
    return undefined; 
}