
import ReactDOM from 'react-dom/client';
import './index.css';
import './assets/style/scrollbar.scss'
import "./assets/style/global.scss";
import "./assets/style/tailwind.scss";
import reportWebVitals from './reportWebVitals';
import { BrowserRouter } from 'react-router-dom';
import App from './App';
import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { setupInterceptors } from './composables/request';
// Create Root renderer
const root = ReactDOM.createRoot(document.getElementById('root')!);
function SetupInterceptorsOnLoad() {
  const navigate = useNavigate();

  useEffect(() => {
    setupInterceptors(navigate);
  }, [navigate]); 
  return null; 

}

// Using the Root renderer to render applications
root.render(
  <BrowserRouter>
   <SetupInterceptorsOnLoad />
    <App /> 
  </BrowserRouter>
);

// Report on Web Vitals (Performance Metrics)
reportWebVitals();
