import { makeAutoObservable, autorun } from 'mobx';

class userStore {
    // Status data
    state = {
        gaea_plugin_token: '',
        gaea_plugin_status: '',
        userInfo: {} as any, // User Information
        goodhoodIdCard: 0
    };

    constructor() {
        makeAutoObservable(this);
        const gaea_plugin_token = sessionStorage.getItem('gaea_plugin_token');
        const gaea_plugin_status = sessionStorage.getItem('gaea_plugin_status');
        const storedItem = sessionStorage.getItem('userInfo');
        const goodhoodIdCard = sessionStorage.getItem('goodhoodIdCard');
        if (gaea_plugin_token && this.isValidJson(gaea_plugin_token)) {
            this.state.gaea_plugin_token = JSON.parse(gaea_plugin_token);
        }
        if (gaea_plugin_status && this.isValidJson(gaea_plugin_status)) {
            this.state.gaea_plugin_status = JSON.parse(gaea_plugin_status);
        }
        if (storedItem && this.isValidJson(storedItem)) {
            this.state.userInfo = JSON.parse(storedItem);
        }
        if (goodhoodIdCard && this.isValidJson(goodhoodIdCard)) {
            this.state.goodhoodIdCard = JSON.parse(goodhoodIdCard);
        }
        autorun(() => {
            sessionStorage.setItem('gaea_plugin_token', JSON.stringify(this.state.gaea_plugin_token));
            sessionStorage.setItem('gaea_plugin_status', JSON.stringify(this.state.gaea_plugin_status));
            sessionStorage.setItem('userInfo', JSON.stringify(this.state.userInfo));
            sessionStorage.setItem('goodhoodIdCard', JSON.stringify(this.state.goodhoodIdCard));
        });
    }

    // Helper function to check if a string is valid JSON
    isValidJson(value: string): boolean {
        try {
            JSON.parse(value);
            return true;
        } catch (e) {
            return false;
        }
    }

    setUserInfo(val: any) {
        this.state.userInfo = val;
    }

    setToken(val: any) {
        this.state.gaea_plugin_token = val;
    }
    setTokenStatus(val: any) {
        this.state.gaea_plugin_status = val;
    }
    setGoodhoodIdCard(val: any) {
        this.state.goodhoodIdCard = val;
    }

    clearData() {
        this.state.gaea_plugin_token = '';
        this.state.gaea_plugin_status = '1';
        this.state.goodhoodIdCard = 0;
        this.state.userInfo = {};
    }
}

export default new userStore();
