import axios from 'axios';
import { message } from 'antd';
import userStore from '../store/user';

const axiosInstance = axios.create({
  baseURL: 'https://api.aigaea.net/api',
});

let is401AlertShown = false;
let activeErrorMessages = new Set();

const handle401Error = (navigate: any, res: any) => {
  message.error(res.msg || res.data || 'Network failure');
};

export const setupInterceptors = (navigate: any) => {
  if ((axiosInstance as any)._interceptorsSetup) {
    return;
  }
  (axiosInstance as any)._interceptorsSetup = true;

  axiosInstance.interceptors.request.use(
    (config) => {
      const token = userStore.state.gaea_plugin_token;
      if (token) {
        config.headers.Authorization = `Bearer ${token}`;
        config.headers['Content-Type'] = 'application/json';
      }
      return config;
    },
    (error) => {
      console.error('Request failed:', error);
      return Promise.reject(error);
    }
  );

  axiosInstance.interceptors.response.use(
    (response) => {
      if (response.data.code === 200) {
        return response.data;
      } else {
        activeErrorMessages.clear();
        if (response.data.code === 401) {
          handle401Error(navigate, response.data);
          return Promise.reject(response);
        } else {
          return Promise.reject(response.data);
        }
      }
    },
    (error) => {
      activeErrorMessages.clear();
      console.error('Request failed:', error);
      return Promise.reject(error);
    }
  );
};

export const getAxiosInstance = (navigate?: any) => {
  if (navigate && !(axiosInstance as any)._interceptorsSetup) {
    setupInterceptors(navigate);
  }
  return axiosInstance;
};

export default axiosInstance;