import React  from 'react';
import { Image } from 'antd';
import { CloseOutlined } from '@ant-design/icons';
import LogOutSvg from "./LogOutSvg"
import userStore from "../../store/user"


interface UserProfileProps {
    open: boolean;
    onCloseDialog?: (isOpen: boolean) => void;
}

const UserProfile: React.FC<UserProfileProps> = ({ open, onCloseDialog }) => {
    if (!open) {
        return null;
    }
    const handleClose = () => {
        if (onCloseDialog) {
            onCloseDialog(false);
        }
    };
    const logOutHandle = () => {
        handleClose();
        userStore.clearData()
        chrome.runtime.sendMessage({ action: "logout" }, (response) => {
            if (chrome.runtime.lastError) {
                return;
            }
            if (response && response.success) {
                userStore.setToken('');
            } else {
                console.log("Logout failed:", response);
            }
        });
    };
    return (
        <div className="w-[95%] absolute top-1/2 left-1/2 -translate-y-1/2 -translate-x-1/2 border border-white/10 py-1
         z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm pr-3">
            <span className='text-[#666] hover:text-[#EBEBEB] absolute top-2 right-2 text-[14px] cursor-pointer' onClick={handleClose}><CloseOutlined /></span>
            <div className="overflow-hidden flex flex-col space-y-2 px-2 pb-4">
                <div className="w-full h-[140px] flex items-center justify-between relative top-2 ">
                    <div className="w-[60px] h-full relative rotate-180">
                        <img
                            src={require('../../assets/images/door.png')}
                            alt=""
                            className="w-full h-full object-contain absolute top-0 left-0"
                        />
                    </div>

                    <div className="flex items-center space-x-2">
                        <div className="w-[40px] h-[40px] rounded-full overflow-hidden border-2 border-[#ebebeb3f]">
                            <Image
                                src={require('../../assets/images//head/god.png')}
                                fallback="/images/public/head/god.png"
                                className="w-full h-full object-cover"
                                preview={false}
                            />
                        </div>
                        <div className='flex-1'>
                            <div
                                className="text-[#B0B0B0] cursor-pointer hover:text-[#EBEBEB] space-x-1 flex items-center" >
                                <span className="text-[12px] font-normal">{userStore.state?.userInfo.name}</span>
                            </div>
                            <div className="flex items-center space-x-1 text-[#B0B0B0] text-[12px] font-normal cursor-pointer hover:text-white">
                                <span>uid :{userStore.state?.userInfo.uid}</span>
                            </div>
                        </div>
                    </div>

                    <div className="w-[60px] h-full relative -rotate-360">
                        <img
                            src={require('../../assets/images/door.png')}
                            alt=""
                            className="w-full h-full object-contain absolute top-0 left-0"
                        />
                    </div>
                </div>
                <div onClick={logOutHandle} className="flex items-center justify-end  space-x-1 text-[#B0B0B0] hover:text-[#EBEBEB] cursor-pointer text-sm font-normal">
                    <LogOutSvg />
                    <span>Log out</span>
                </div>
            </div>
        </div>
    );
};

export default UserProfile;