import "../assets/style/Index.scss";
import { useState, useEffect, useMemo, useCallback, useRef } from "react";
import userStore from "../store/user";
import { authSession, chatHistory, aiComplete, aiList, godhoodAddress } from "../api/user";
import RulesModal from "../components/Index/RulesModal";
import UserProfile from "../components/Index/UserProfile";
import TrainingEndPrompt from "../components/Index/TrainingEndPrompt";
import GaeaAiSvg from "../components/Index/GaeaAiSvg"
import StartSvg from "../components/Index/StartSvg"
import SubmitSvg from "../components/Index/SubmitSvg"
import EarnInfo from "../components/Index/EarnInfo";
import Step1 from "../components/Index/Step1";
import { marked } from 'marked'
import { message, Button } from 'antd';
import { getStringByNumber, getNumberByString_, getStringAccuracy, getNumberByString } from '../utils/dict'

const Index = () => {
    const messagesContainer = useRef<HTMLDivElement>(null);
    // whatStepIsIt
    const [whatStepIsIt, setWhatStepIsIt] = useState("step1");
    const [runLoading, setRunLoading] = useState(false);
    const [openRulesModal, setOpenRulesModal] = useState(false);
    const [openUserProfile, setOpenUserProfile] = useState(false);
    const [openTrainingEndPrompt, setOpenTrainingEndPrompt] = useState(false);

    const [showRestart, setShowRestart] = useState(false);
    const [exporting, setExporting] = useState(false);
    const [answerList, setAnswerList] = useState<Array<{ content: string, role: string, status?: string }>>([]);
    const [problemText, setProblemText] = useState("");
    const [displayText, setDisplayText] = useState("");
    const [exportingBool, setExportingBool] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [accuracyIndex, setAccuracyIndex] = useState<any>(null);
    const [isChooseEmotions, setIsChooseEmotions] = useState(false)
    const [loadingBtn, setLoadingBtn] = useState(false)
    const [messageApi, contextHolder] = message.useMessage();
    const [aiListLoading, setAiListLoading] = useState(false)
    const [aiSignInRecord, setAiSignInRecord] = useState<any>([])
    const [trainingReward, setTrainingReward] = useState({ soul: 0, blindbox: 0 })
    // Data
    const [emotionsArr] = useState([
        { name: 'Positive', id: 1 },
        { name: 'Neutral', id: 2 },
        { name: 'Negative', id: 3 }
    ]);

    const [accuracyList] = useState([
        { id: 0, name: 'Accurate' },
        { id: 2, name: 'Inaccurate' }
    ]);


    const showInput = useMemo(() => {
        const lastObject = answerList[answerList.length - 1];
        return lastObject?.role !== "200";
    }, [answerList]);

    const canChat = useMemo(() => {
        const lastObject = answerList[answerList.length - 1];
        return lastObject?.role === "405" || lastObject?.role === "400"
    }, [answerList]);

    const canEmotionalCheckIn = useMemo(() => {
        const lastObject = answerList[answerList.length - 1];
        return lastObject?.role === "200"
    }, [answerList])
    const getAuthSession = async () => {
        const res: any = await authSession();
        if (res.code === 200) {
            if (res.data?.eth_address || res.data?.sol_address) {
                getGodhoodAddress(res.data?.eth_address || res.data?.sol_address)
            }
            userStore.setUserInfo(res.data)

        }
    };
    const showModal = () => {
        setOpenRulesModal(true);
    };
    const handleAgree = () => {
        setWhatStepIsIt("step2");
        sendEmotionRequest(false);
    };

    const finalizeResponse = () => {
        setExportingBool(false);
        setAnswerList(prev => {
            const newAnswerList = prev.map(item =>
                item.status === 'padding' ? { ...item, status: '' } : item
            );
            return newAnswerList;
        });
        setDisplayText('');
        scrollToNextSection()
    };

    const handleResponse = (code: number, msg: string) => {
        setAnswerList(prevAnswerList => {
            const lastAnswer = prevAnswerList[prevAnswerList.length - 1];
            if (!lastAnswer) {
                if (code === 200) {
                    setAccuracyIndex(getNumberByString(msg))
                    return [{ content: msg, role: '200', status: 'padding' }];
                }
                return prevAnswerList;
            };

            switch (code) {
                case 200:
                    const newAnswerList200 = [...prevAnswerList];
                    const lastItem200 = newAnswerList200[newAnswerList200.length - 1];
                    if (lastItem200 && lastItem200.role === 'assistant' && lastItem200.content === '') {
                        lastItem200.role = '200';
                        lastItem200.content = msg;
                    } else {
                        newAnswerList200.push({ content: msg, role: '200', status: 'padding' });
                    }
                    setDisplayText(msg);
                    setRunLoading(false);
                    return newAnswerList200;

                case 206:
                    setDisplayText(prev => prev + msg);
                    const newAnswerList206 = [...prevAnswerList];
                    const lastItem206 = newAnswerList206[newAnswerList206.length - 1];
                    if (lastItem206) {
                        lastItem206.content = lastItem206.content + msg;
                    }
                    scrollToNextSection();
                    return newAnswerList206;

                case 404:
                    setDisplayText('Retry');
                    setExportingBool(false);
                    return prevAnswerList;

                case 405:
                    const newAnswerList405 = [...prevAnswerList];
                    const lastItem405 = newAnswerList405[newAnswerList405.length - 1];
                    if (lastItem405) {
                        lastItem405.role = "405";
                    }
                    return newAnswerList405;

                case 400:
                    const newAnswerList400 = [...prevAnswerList, { content: msg, role: '400', status: '' }];
                    return newAnswerList400;

                default:
                    return prevAnswerList;
            }
        });
    }

    const sendEmotionRequest = async (bool = true, mark = false) => {
        if (mark) {
            if (showRestart || exporting) return;
            setWhatStepIsIt("step2");
            setAnswerList([]);
        }

        if (exportingBool || (bool && !problemText)) return;

        setExportingBool(true);

        if (bool) {
            setAnswerList(prev => {
                const newAnswerList = [...prev, { content: problemText, role: "user" }];
                return newAnswerList;
            });
            scrollToNextSection()
        }

        setAnswerList(prev => {
            const newAnswerList = [
                ...prev,
                { content: "", role: "assistant", status: "padding" }
            ];
            return newAnswerList;
        });

        const data = { message: problemText, mark };
        setProblemText("");

        try {
            const body = await fetchEmotionResponse(data);
            if (!body) throw new Error("No readable stream found in response");

            const reader = body.getReader();
            const decoder = new TextDecoder("utf-8");
            let accumulatedData = "";

            const readStream = () => {
                reader.read().then(({ done, value }) => {
                    if (value) {
                        const chunk = decoder.decode(value, { stream: !done });
                        accumulatedData += chunk;

                        let jsonStart = accumulatedData.indexOf("{");
                        while (jsonStart !== -1) {
                            const jsonEnd = accumulatedData.indexOf("}", jsonStart);
                            if (jsonEnd !== -1) {
                                const jsonString = accumulatedData.substring(
                                    jsonStart,
                                    jsonEnd + 1
                                );
                                try {
                                    const { code, msg } = JSON.parse(jsonString);
                                    handleResponse(code, msg);
                                } catch (error) {
                                    // JSON parse error
                                }
                                accumulatedData = accumulatedData.substring(jsonEnd + 1);
                                jsonStart = accumulatedData.indexOf("{");
                            } else {
                                break;
                            }
                        }
                    }

                    if (!done) {
                        setTimeout(readStream, 50);
                    } else {
                        finalizeResponse();
                    }
                });
            };

            readStream();
        } catch (error) {
            console.error("Error:", error);
            setExportingBool(false);
        }
    };

    const fetchEmotionResponse = async (data: { message: string }) => {
        const BASE_URL = 'https://api.aigaea.net';
        setRunLoading(true);
        const response = await fetch(`${BASE_URL}/api/ai/chat`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${userStore.state.gaea_plugin_token}`,
            },
            body: JSON.stringify(data),
        });

        if (!response.ok) {
            setRunLoading(false);
            throw new Error('Network response was not ok');
        }

        return response.body;
    };
    // Methods
    const formatCompletionMessage = (content: string) => {
        return `Thank you for training GODHOOD ENGINE. Your emotion today is
                "${getStringByNumber(getNumberByString_(content, 0))}" 
                and you have rated this training session as
                "${getStringAccuracy(getNumberByString_(content, 1))}". We look forward
                to meeting you again in the emotional coordinates next time.`
    }
    const handleApiError = (error: any) => {
        messageApi.open({
            type: 'error',
            content: typeof error === 'string' ? error : 'An error occurred',
        });
    }
    // 
    const isTtAccurateHandle = (num: number) => {
        const lastObject = answerList[answerList.length - 1]
        if (!lastObject) return

        if (num === 0) {
            const emotion = getNumberByString(lastObject['content'] || 2)
            setAiComplete(num, emotion)
        } else {
            setIsChooseEmotions(true)
        }
    }
    const isChooseEmotionsHandle = (emotionId: number) => {
        if (loadingBtn) return
        setAccuracyIndex(emotionId)
        setAiComplete(2, emotionId)
    }
    const setAiComplete = async (num: number, emotion: number) => {
        try {
            const lastObject = answerList[answerList.length - 1];
            if (!lastObject) return;

            setLoadingBtn(true);
            const isPayCard = userStore.state.goodhoodIdCard;
            if (emotion === null || emotion === undefined) {
                messageApi.error('Please select an emotion');
                return;
            }

            const detail = `${emotion}_${num}_${isPayCard || 0}`;
            const res: any = await aiComplete({ detail });

            if (res.code === 200) {
                setOpenTrainingEndPrompt(true)
                setTrainingReward({ soul: res.data.soul, blindbox: res.data.blindbox })
                // getAiList()
                getChatHistory()
                setAiSignInRecord({ cycle: [], today: detail })
            } else {
                handleApiError(res.msg);
            }
        } catch (error) {
            handleApiError(error);
        } finally {
            setLoadingBtn(false);
        }
    };
    const getChatHistory = async () => {
        try {
            if (!userStore.state.gaea_plugin_token) return
            setIsLoading(true)
            const res = await chatHistory() as any
            if (res.code === 200 && res.data && res.data.length > 0) {
                setWhatStepIsIt("step2");
                setAnswerList(res.data)
                scrollToNextSection()
            }
        } catch (error) {
            setIsLoading(false)
            console.log(error)
        } finally {
            setIsLoading(false)
        }
    }
    const scrollToNextSection = useCallback(() => {
        if (messagesContainer.current) {
            messagesContainer.current.scrollTop = messagesContainer.current.scrollHeight;
        }
    }, []);
    // getaList
    const getAiList = async () => {
        try {

            setAiListLoading(true)
            const res = await aiList() as any;
            if (res.code === 200) {
                setAiSignInRecord(res.data)
            }
        } catch (error) {
            console.log(error);
            setAiListLoading(false)

        } finally {
            setAiListLoading(false)
        }
    }
    const handleLogout = () => {
        setOpenUserProfile(true)
    };
    const getGodhoodAddress = async (address: string) => {
        const res: any = await godhoodAddress({ address })
        if (res.code === 200) {
            userStore.setGoodhoodIdCard(res.data)
        }
    }
    useEffect(() => {
        if (!userStore.state.gaea_plugin_token) return
        getAuthSession();
        getAiList()
        getChatHistory()
    }, []);

    return (
        <div className="w-full h-[600px] flex flex-col items-center pt-3 relative ">
            <EarnInfo onLogout={handleLogout} />
            <div className="w-full flex-1 overflow-hidden  ai-chart py-2  relative ">
                {!isLoading && !aiListLoading ? (
                    aiSignInRecord.today ? (<div className="w-full h-full flex flex-col justify-between  text-[#EBEBEB] px-4   ">
                        {answerList.length > 0 ? (
                            <div className="w-full flex-1 text-[#ebebeb] overflow-y-auto px-3 ">
                                <div className="w-full flex-1 space-y-2   " >
                                    {answerList.map((answer, idx) => (
                                        <div className="flex flex-col" key={idx}>
                                            <div className={`w-full flex flex-col mb-4 space-y-3 ${answer.role === 'user' ? 'justify-end' : ''}`} >
                                                {answer.role !== 'user' && (
                                                    <div className={`flex items-center space-x-2 pl-1 text-green-600 `}>
                                                        <GaeaAiSvg />
                                                        <span className="text-[10px] font-mono font-bold uppercase tracking-[0.15em] leading-[10px]">
                                                            GODHOOD ENGINE
                                                        </span>
                                                    </div>
                                                )}

                                                {answer.role === 'user' && (
                                                    <div
                                                        className={`flex items-center justify-end space-x-2 pl-1 text-white-600 `} >
                                                        <span className="text-[10px] font-mono font-bold uppercase tracking-[0.15em] leading-[10px]">
                                                            TRAINER
                                                        </span>
                                                    </div>
                                                )}
                                                <div className={`flex  ${answer.role === 'user' ? 'justify-end' : ''}`}>
                                                    {answer.role === '200' ?
                                                        (<div className="flex justify-end bg-[#0A0A0A]/90 text-[12px] border border-[#222] rounded-[16px] rounded-tl-none backdrop-blur-sm p-2 md:p-4   shadow-sm">
                                                            {formatCompletionMessage(answer.content)}
                                                        </div>) : (<div dangerouslySetInnerHTML={{ __html: marked(answer.content) as string }}
                                                            className={`${answer.role === 'user'
                                                                ? 'bg-white text-black shadow-[0_4px_20px_rgba(0,0,0,0.5)] rounded-tr-none'
                                                                : 'bg-[#0A0A0A]/90 rounded-tl-none'
                                                                } w-fit  break-words p-2 md:p-4  shadow-sm backdrop-blur-sm  shadow-sm border border-[#222] rounded-[16px] text-[12px]`} >
                                                        </div>)}

                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ) : (
                            <div className="space-y-2 ">
                                <div className={`flex items-center space-x-2 pl-1 text-green-600 `}>
                                    <GaeaAiSvg />
                                    <span className="text-[10px] font-mono font-bold uppercase tracking-[0.15em] leading-[10px]">
                                        GODHOOD ENGINE
                                    </span>
                                </div>
                                <div className="flex justify-end bg-[#0A0A0A]/90 border border-[#222] rounded-[12px] rounded-tl-none backdrop-blur-sm p-2 md:p-4 shadow-sm">
                                    {formatCompletionMessage(aiSignInRecord.today)}
                                </div>
                            </div>
                        )}

                        <div className="flex justify-end pr-4 pt-2" >
                            <Button
                                className={`w-[150px]  h-8 btn-tech-base border-none text-[9px] text-neutral-400 
                                    ${getStringByNumber(getNumberByString_(aiSignInRecord.today, 0))}`} disabled >
                                <span className="text-[#EBEBEB]">Training completed</span>
                            </Button>
                        </div>
                    </div>) : (
                        <div className="w-full h-full px-1  pb-2 space-y-3  bg-black flex flex-col items-center  relative">
                            {whatStepIsIt && whatStepIsIt === "step1" && (
                                <Step1 onStartTraining={showModal} />
                            )}
                            {whatStepIsIt && whatStepIsIt === "step2" && (
                                <div className="w-full h-full flex flex-col items-center overflow-hidden space-y-2 "  >
                                    <div className="w-full flex-1 text-[#ebebeb] overflow-y-auto px-3" ref={messagesContainer} >
                                        <div className="w-full flex-1 py-3 space-y-2   " >
                                            {answerList.map((answer, idx) => (
                                                <div className="flex flex-col" key={idx}>
                                                    <div className={`w-full flex flex-col mb-4 space-y-3 ${answer.role === 'user' ? 'justify-end' : 'flex-row-reverse'}`} >
                                                        {answer.role !== 'user' && (
                                                            <div className={`flex items-center space-x-2 pl-1 text-green-600 `}>
                                                                <GaeaAiSvg />
                                                                <span className="text-[10px] font-mono font-bold uppercase tracking-[0.15em] leading-[10px]">
                                                                    GODHOOD ENGINE
                                                                </span>
                                                            </div>
                                                        )}

                                                        {answer.role === 'user' && (
                                                            <div
                                                                className={`flex items-center justify-end space-x-2 pl-1 text-white-600 `} >
                                                                <span className="text-[10px] font-mono font-bold uppercase tracking-[0.15em] leading-[10px]">
                                                                    TRAINER
                                                                </span>
                                                            </div>
                                                        )}

                                                        <div className={`flex-1 flex ${answer.role === 'user' ? 'justify-end' : ''}`}>
                                                            <div className={`flex items-center flex-wrap break-all text-[16px] ${answer.role === 'user' ? 'bg-[#1d1c1ca0] rounded-lg' : ''}`} >
                                                                {answer.role === 'assistant' && answer.status === 'padding' ? (
                                                                    displayText !== 'Retry' ? (
                                                                        <div className="flex justify-end bg-[#0A0A0A]/90 border border-[#222] rounded-[16px] rounded-tl-none backdrop-blur-sm p-2 md:p-4 max-w-3xl shadow-sm">
                                                                            <div
                                                                                className="break-words text-[12px]"
                                                                                dangerouslySetInnerHTML={{ __html: marked(displayText) as string }}
                                                                            />
                                                                            {!displayText && <span className="cursor">_</span>}
                                                                        </div>
                                                                    ) : (
                                                                        <div className="w-fit text-[12px] hover:scale-[1.1] duration-500 text-[#EBEBEB] rounded-full text-center u-line-1 cursor-pointer">
                                                                            Retry
                                                                        </div>
                                                                    )
                                                                ) : (
                                                                    <>
                                                                        {answer.role == '200' && (
                                                                            <div
                                                                                className={`bg-[#0A0A0A]/90 rounded-tl-none break-words p-2 md:p-4 max-w-3xl shadow-sm backdrop-blur-sm max-w-3xl shadow-sm border border-[#222] rounded-[16px] text-[12px]`} >
                                                                                {formatCompletionMessage(answer.content)}
                                                                            </div>
                                                                        )}
                                                                        {(answer.role === '405' || answer.role === '400') && (
                                                                            <div>
                                                                                It looks like you didn't follow the required process for training.
                                                                                Unfortunately, you won't receive the task reward. Please try again tomorrow.
                                                                            </div>
                                                                        )}
                                                                        {answer.role !== '200' && answer.role !== '405' && (
                                                                            <div
                                                                                dangerouslySetInnerHTML={{ __html: marked(answer.content) as string }}
                                                                                className={`${answer.role === 'user'
                                                                                    ? 'bg-white text-black shadow-[0_4px_20px_rgba(0,0,0,0.5)] rounded-tr-none'
                                                                                    : 'bg-[#0A0A0A]/90 rounded-tl-none'
                                                                                    } break-words p-2 md:p-4 max-w-3xl shadow-sm backdrop-blur-sm max-w-3xl shadow-sm border border-[#222] rounded-[16px] text-[12px]`}
                                                                            />
                                                                        )}

                                                                    </>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                    {showInput && (
                                        <div className="w-full relative flex items-center bg-black border border-[#222] px-3 py-3 shadow-[0_10px_40px_rgba(0,0,0,0.5)] transition-all focus-within:border-[#444] hover:border-[#333] rounded-xl">
                                            <div className="w-4 h-4 text-[#555] shrink-0 ">
                                                <StartSvg />
                                            </div>
                                            <div className="w-[1px] h-5 bg-[#333] mx-4 shrink-0 "></div>
                                            <input
                                                value={problemText}
                                                onChange={(e) => setProblemText(e.target.value)}
                                                placeholder="Check-in Your emotions Based on the Prompt"
                                                style={{ height: '20px' }}
                                                className="flex-1 bg-transparent text-[#e5e5e5] placeholder-[#444] focus:outline-none font-sans text-[14px] h-full tracking-wide"
                                                onKeyDown={(e) => e.key === 'Enter' && sendEmotionRequest(true)}
                                                disabled={canChat}
                                            />

                                            <div
                                                className={exporting || problemText === '' ? 'cursor-not-allowed text-[#666666]' : 'text-[#EBEBEB] cursor-pointer'}
                                                onClick={() => sendEmotionRequest(true)}
                                            >
                                                {exportingBool ? (<div className="animate-spin rounded-full h-6 w-6 border-b-2 border-white"></div>) : (<SubmitSvg />)}
                                            </div>
                                        </div>
                                    )}
                                    {canEmotionalCheckIn && (
                                        !isChooseEmotions ? (
                                            <div className="flex items-center justify-end flex-wrap space-x-3">
                                                {accuracyList.map((accuracy_item, accuracy_index) => (
                                                    <button
                                                        key={accuracy_index}
                                                        className={`w-[150px] h-8 btn-tech-base btn-outline text-[9px] text-neutral-400 ${accuracy_index === accuracyIndex && loadingBtn ? 'opacity-70' : ''}`}
                                                        disabled={loadingBtn || (accuracy_index === accuracyIndex && loadingBtn)}
                                                        onClick={() => isTtAccurateHandle(accuracy_item.id)}>
                                                        {loadingBtn && <div className="animate-spin rounded-full h-2 w-2 border-b-2 border-white"></div>}
                                                        <span>{accuracy_item.name}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        ) : (
                                            <div className="w-full flex items-end justify-end pr-5">
                                                <div className="w-fit flex flex-col items-center space-y-3">
                                                    <p className="text-[#ebebeba0] text-[12px] font-[200] text-center">
                                                        Thank you for your feedback! Please tell us your<br /> true emotions to help AI understand its
                                                        errors.
                                                    </p>
                                                    <div className="flex items-center justify-end flex-wrap space-x-3">
                                                        {emotionsArr.map(emotions_item => (
                                                            <button
                                                                key={emotions_item.id}
                                                                className={`px-3 btn-tech-base btn-outline mb-4 ${emotions_item.name}`}
                                                                style={{ height: '32px', border: 'none' }}
                                                                disabled={emotions_item.id === accuracyIndex && loadingBtn}
                                                                onClick={() => isChooseEmotionsHandle(emotions_item.id)}>
                                                                <div className="text-[12px] text-[#EBEBEB] flex itecons-center space-x-1">
                                                                    {loadingBtn && accuracyIndex === emotions_item.id ? (
                                                                        <>
                                                                            <div className="animate-spin rounded-full h-2 w-2 border-b-2 border-white"></div>
                                                                            <span>{emotions_item.name}</span>
                                                                        </>
                                                                    ) : (
                                                                        emotions_item.name
                                                                    )}
                                                                </div>
                                                            </button>
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                        )
                                    )}
                                </div>
                            )
                            }

                        </div >
                    )
                ) : (<div className="w-full h-full flex items-center justify-center">
                    <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-white"></div>
                </div>
                )}
            </div>
            <RulesModal
                open={openRulesModal}
                onCloseDialog={(isOpen: boolean) => setOpenRulesModal(isOpen)}
                onAgree={() => {
                    handleAgree();
                }}
            />
            <UserProfile
                open={openUserProfile}
                onCloseDialog={(isOpen: boolean) => setOpenUserProfile(isOpen)}

            />
            <TrainingEndPrompt open={openTrainingEndPrompt} data={{ soul: trainingReward.soul, blindbox: trainingReward.blindbox }}
                onCloseDialog={(isOpen: boolean) => setOpenTrainingEndPrompt(isOpen)} />
        </div >

    );
};

export default Index;