import React from 'react';
interface RulesModalProps {
    open: boolean;
    onCloseDialog?: (isOpen: boolean) => void;
    onAgree?: () => void;
}

const RulesModal: React.FC<RulesModalProps> = ({ open, onCloseDialog, onAgree }) => {
    if (!open) {
        return null;
    }

    const handleAgree = () => {
        if (onAgree) {
            onAgree();  
        }
        if (onCloseDialog) {
            onCloseDialog(false);
        }
    };
    const handleClose = () => {
        if (onCloseDialog) {
            onCloseDialog(false);
        }
    };

    return (
        <div className=" absolute inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm pr-3">
            <div className="max-h-[90vh]  overflow-hidden flex flex-col space-y-8 px-5 pb-6">
                <div className="w-full text-center text-[28px] text-[#EBEBEB] font-[700]">Training Reminders </div>
                <div className=" text-[#EBEBEB] text-[14px] space-y-6">
                    <p>1.We ensure that all your private content in the Emotional Coordinates will not be leaked. Please
                        feel confident using the Emotional Coordinates feature.</p>
                    <p>2.Our mission is to make AI smarter, so please follow the AI’s prompts during the conversation.
                        If you do not follow the correct process, your training may fail, and you won’t receive any
                        rewards.</p>
                    <p>3.Warning: We do not welcome uncivilized trainers. Your actions can affect the purity of the AI's
                        data. If inappropriate behavior is detected, you may not receive rewards or may even have your
                        training privileges revoked.</p>
                </div>
                <div className="flex items-center justify-center space-x-3">
                    <button  className={`w-[150px] h-8 btn-tech-base btn-outline text-[9px] text-neutral-400 `} onClick={handleAgree} >Agree</button>
                    <button  className={`w-[150px] h-8 btn-tech-base btn-outline text-[9px] text-neutral-400 `} onClick={handleClose}>Cancel</button>

                </div>
            </div>
        </div>
    );
};

export default RulesModal;