import { useState, useEffect } from 'react';
import type { FormProps } from 'antd';
import { Button, Form, Input, message, Checkbox, CheckboxProps } from 'antd';
import { LockOutlined, UserOutlined, MailOutlined } from '@ant-design/icons';
import userStore from "../store/user"
import CryptoJS from 'crypto-js';
import '../assets/style/loginPage.scss'
import { authLogin, authRegister, googleAuth } from '../api/user';

type FieldType = {
    email?: string;
    username?: string;
    password?: string;
    remember_me?: boolean;
    recaptcha_token?: string;
};

const LoginPage = () => {
    const [loading, setLoading] = useState(false);
    const [googleLoading, setGoogleLoading] = useState(false);
    const [showShake, setShowShake] = useState(false);
    const [doYouAgree, setDoYouAgree] = useState(false);
    const [isLoginMode, setIsLoginMode] = useState(true);
    const [forgotPassword, setForgotPassword] = useState(false);
    const [messageApi] = message.useMessage();
    const [form] = Form.useForm<FieldType>();

    const toggleMode = () => {
        setIsLoginMode(!isLoginMode);
        setForgotPassword(false);
        form.resetFields(); 
    };

    // google
    const handleGoogleAuth = async () => {
        try {
            setGoogleLoading(true)
            const res: any = await googleAuth()
            if (res && res.code === 200) {
                window.open(res.data.url, '_blank')
            }

        } catch (error) {
            console.log(error, 'error')
            setGoogleLoading(false)
        } finally {
            setGoogleLoading(false)
        }

    }
    const loginHandle = async (values: FieldType) => {
        try {
            setLoading(true);
            const plugInId = 'cpjicfogbgognnifjgmenmaldnmeeeib'
            const username = values.username?.trim()
            const password = CryptoJS.SHA256(values.password || '').toString(CryptoJS.enc.Hex).trim()
            const recaptcha_token = CryptoJS.SHA256(`${plugInId}${username}${password.slice(0, 20)}`).toString(CryptoJS.enc.Hex)
            const params = {
                username: username || '',
                password: password,
                remember_me: values.remember_me || false,
                recaptcha_token: recaptcha_token || ''
            };

            const res = await authLogin({ ...params }) as any;

            if (res && res.code === 200) {
                userStore.setToken(res.data.token);
            } else {
                messageApi.open({
                    type: 'error',
                    content: res.msg || 'Login failed',
                });
            }
        } catch (error: any) {
            messageApi.open({
                type: 'error',
                content: error.msg || 'Login failed',
            });
        } finally {
            setLoading(false);
        }
    };

    const registerHandle = async (values: FieldType) => {
        try {
            if (!doYouAgree) {
                setShowShake(true);
                setTimeout(() => {
                    setShowShake(false);
                }, 500);
                return;
            }

            setLoading(true);
            const plugInId = 'cpjicfogbgognnifjgmenmaldnmeeeib'
            const username = values.username?.trim()
            const password = CryptoJS.SHA256(values.password || '').toString(CryptoJS.enc.Hex).trim()
            const recaptcha_token = CryptoJS.SHA256(`${plugInId}${username}${password.slice(0, 20)}`).toString(CryptoJS.enc.Hex)
            const params = {
                email: values.email?.trim() || '',
                username: username || '',
                password: password,
                recaptcha_token: recaptcha_token || '',
                referral_code: ''
            };

            const res: any = await authRegister({ ...params });
            setLoading(false);
            if (res && res.code === 200) {
                message.success('Register successful');
                loginHandle({
                    username: params.username,
                    password: values.password,
                    recaptcha_token: values.recaptcha_token,
                    remember_me: false
                });
            } else {
                message.error(res.msg);
            }
        } catch (error) {
            console.log(error);
            setLoading(false);
        }
    };
    const onChange: CheckboxProps['onChange'] = (e) => {
        setDoYouAgree(e.target.checked)
    };
    const onFinish: FormProps<FieldType>['onFinish'] = async (values) => {
        if (loading) return;

        if (isLoginMode) {
            await loginHandle(values);
        } else {
            await registerHandle(values);
        }
    };

    const onFinishFailed: FormProps<FieldType>['onFinishFailed'] = (errorInfo) => {
        console.log('Failed:', errorInfo);
    };

   
    //  Turnstile token
    const toUpdateTurnstileToken = (token: string) => {
        form.setFieldsValue({ recaptcha_token: token });
    };
    useEffect(() => {
        //  content script   Turnstile token 
        const handleMessage = (event: MessageEvent) => {
            if (event.data.type === 'TURNSTILE_TOKEN' && event.data.token) {
                form.setFieldsValue({ recaptcha_token: event.data.token });
            }
        };

        window.addEventListener('message', handleMessage);
        return () => {
            window.removeEventListener('message', handleMessage);
        };
    }, [form]);
    return (
        <div className="login-page">
            <div className="auth-container">
                <div className="header-text">
                    <div className="w-50 h-10 cursor-pointer mx-auto">
                        <img src={require(`../assets/images/logo.png`)} alt="" className="w-full h-full object-contain" />
                    </div>
                    <p id="sub-title" className="text-[18px] mt-1" style={{ letterSpacing: '4px' }}>
                        Human Sense for A!
                    </p>
                </div>

                <Button
                    className="btn-google"
                    onClick={handleGoogleAuth}
                    loading={googleLoading}
                >
                    <svg className="google-icon" viewBox="0 0 48 48">
                        <path fill="#EA4335"
                            d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z" />
                        <path fill="#4285F4"
                            d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z" />
                        <path fill="#FBBC05"
                            d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z" />
                        <path fill="#34A853"
                            d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z" />
                    </svg>
                    <span id="google-text" className="text-[#333]">
                        {isLoginMode ? 'Sign in with Google' : 'Sign up with Google'}
                    </span>
                </Button>

                <div className="divider">
                    <span>OR</span>
                </div>

                <Form
                    form={form}
                    name="login_register_form"
                    layout="vertical"
                    initialValues={{ remember_me: true }}
                    onFinish={onFinish}
                    onFinishFailed={onFinishFailed}
                    autoComplete="off"
                    requiredMark={false} >
                    <div className="input-wrapper">
                        <div className={`field-group ${isLoginMode || forgotPassword ? 'field-hidden' : 'field-visible'}`}>
                            <Form.Item<FieldType>
                                label="Email"
                                name="email"
                                rules={[
                                    { required: isLoginMode ? false : true, message: 'Please enter a valid email address' },
                                    { type: 'email', message: 'Please enter a valid email address' }
                                ]}
                            >
                                <Input
                                    prefix={<MailOutlined />}
                                    placeholder="Enter your email"
                                />
                            </Form.Item>
                        </div>
                    </div>

                    {!forgotPassword && (
                        <Form.Item<FieldType>
                            label={isLoginMode ? 'Email or Username' : 'Username'}
                            name="username"
                            rules={[
                                { required: true, message: 'Please enter your username' },
                                { min: 6, message: 'At least 6 characters' }
                            ]}
                        >
                            <Input
                                prefix={<UserOutlined />}
                                placeholder={isLoginMode ? 'Enter your email or username' : 'Enter your username'}
                            />
                        </Form.Item>
                    )}

                    {!forgotPassword && (
                        <Form.Item<FieldType>
                            label="Password"
                            name="password"
                            rules={[
                                { required: true, message: 'Please enter your password' },
                                { min: 8, message: 'At least 8 characters' }
                            ]}
                        >
                            <Input.Password
                                prefix={<LockOutlined />}
                                placeholder="Enter your password"
                            />
                        </Form.Item>
                    )}
                    {/* <Form.Item<FieldType>
                        name="recaptcha_token"
                        rules={[{ required: true, message: 'Please complete the verification' }]}
                    >
                        <PublicTurnstile
                            id="recaptcha_token_container"
                            onSuccess={toUpdateTurnstileToken}
                        />
                    </Form.Item> */}
                    {!isLoginMode && (
                        <div className={`flex items-center text-[#666] set_checkbox_sty mb-2 px-2 ${showShake ? 'shake' : ''}`}>
                            <Checkbox onChange={onChange} />
                            <span className="text-opacity-80 text-[11px] ml-2  ">
                                I have read and agree to
                                <a
                                    className="underline underline-offset-4 cursor-pointer hover:text-[#EBEBEB] ml-1"
                                    href="https://app.aigaea.net/termsConditions"
                                    target="_blank"
                                    rel="noopener noreferrer"
                                >
                                    Terms
                                </a>
                                <span className='px-1'>and</span>
                                <a
                                    className="underline underline-offset-4 cursor-pointer hover:text-[#EBEBEB]"
                                    href="https://app.aigaea.net/privacyPolicy"
                                    target="_blank"
                                    rel="noopener noreferrer"
                                >
                                    Privacy Policy
                                </a>
                            </span>
                        </div>
                    )}
                    <Button
                        className="btn-submit"
                        id="btn-submit"
                        type="primary"
                        htmlType="submit"
                        loading={loading}
                        block>
                        {isLoginMode ? 'Sign in' : 'Sign Up'}
                    </Button>
                </Form>

                <div className="toggle-mode">
                    <span id="toggle-text">
                        {isLoginMode ? "Don't have an account?" : "Already have an account?"}
                    </span>
                    <a id="toggle-link" onClick={toggleMode}>
                        {isLoginMode ? "Create an account" : "Log in"}
                    </a>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;