import { useState, useEffect } from 'react';
import { earnInfo } from '../../api/user';
import userStore from "../../store/user";

interface EarnData {
    total_aitrain: number;
    total_deeptrain: number;
    total_soul: number;
}
interface EarnInfoProps {
    onLogout?: () => void; 
}

const EarnInfo: React.FC<EarnInfoProps> = ({ onLogout }) => {
    const [earnData, setEarnData] = useState<EarnData | null>(null);
    const [loading, setLoading] = useState(true);
    const fetchEarnInfo = async () => {
        try {
            setLoading(true);
            const res: any = await earnInfo();
            if (res.code === 200) {
                const data: EarnData = {
                    total_aitrain: res.data.total_aitrain || 0,
                    total_deeptrain: res.data.total_deeptrain || 0,
                    total_soul: res.data.total_soul || 0
                };
                setEarnData(data);
                console.log('Set earnData:', data);
            }
        } catch (err) {
            console.error('Error fetching earn info:', err);
        } finally {
            setLoading(false);
        }
    };
    useEffect(() => {
        if (!userStore.state.gaea_plugin_token) return

        fetchEarnInfo();
    }, []);

    const total_aitrain = earnData?.total_aitrain ?? 0;
    const total_deeptrain = earnData?.total_deeptrain ?? 0;
    const total_soul = earnData?.total_soul ?? 0;

    return (
        <div className="w-full h-11 flex items-center px-2 ">
            <div onClick={onLogout} className="w-11 h-11 mr-1 rounded-full overflow-hidden cursor-pointer bg-black border-2 border-[#ebebeb9e]">
                <img
                    src={require('../../assets/images//head/god.png')}
                    alt="god"
                    className="w-full h-full object-contain"
                />
            </div>
            <div className="flex-1 h-11 border-l border-y border-[#222] flex flex-col items-center justify-center py-1 relative bg-black">
                <span className="text-[8px] uppercase tracking-wider text-[#555] mb-1 font-bold">
                    Training
                </span>
                <span className="text-[16px] text-white font-bold leading-none font-sans">
                    {loading ? 0 : total_aitrain}
                </span>
            </div>
            <div className="flex-1 h-11 border-l border-y border-[#222] flex flex-col items-center justify-center py-1 bg-black relative">
                <span className="text-[8px] uppercase tracking-wider text-[#555] mb-1 font-bold">
                    Deep Training
                </span>
                <span className="text-[16px] text-white font-bold leading-none font-sans">
                    {loading ? 0 : total_deeptrain}
                </span>
            </div>
            <div className="h-full flex-1 flex  border-y border-x border-[#222] flex flex-col items-center justify-between py-1 bg-black relative overflow-hidden group">
                <div className="w-full h-2 flex-1 flex items-center justify-center relative z-10">
                    <img
                        src={require('../../assets/images/sp.jpg')}
                        alt="Soul Points"
                        className="w-full h-full object-contain"
                    />
                </div>
                <span className="text-[16px] text-white font-bold leading-none font-sans">
                    {loading ? 0 : total_soul}
                </span>
            </div>
        </div>
    );
};

export default EarnInfo;