import React from 'react';
import { Button } from 'antd';
interface TrainingEndPromptProps {
    open: boolean;
    onCloseDialog?: (isOpen: boolean) => void;
    data?: any
}

const TrainingEndPrompt: React.FC<TrainingEndPromptProps> = ({ open, onCloseDialog, data }) => {
    if (!open) {
        return null;
    }

    const handleClose = () => {
        if (onCloseDialog) {
            onCloseDialog(false);
        }
    };

    return (
        <div className=" absolute inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm pr-3">
            <div className="  overflow-hidden flex flex-col space-y-8 px-5 pb-6">
                <div className=" text-[#EBEBEB] text-[14px] space-y-6">
                    <p>
                        Thank you for providing emotional training for GAEA AI agent! This is the reward given to you for this training
                    </p>
                </div>
                <div className="flex items-center justify-center space-x-2">
                    {data?.soul > 0 && (
                        <div className="w-full z-20 flex items-center justify-center space-x-1 ">
                            <div className="w-[82px] mt-1 ">
                                <img  src={require('../../assets/images/sp.jpg')}  alt="" className="w-full h-full object-contain" />
                            </div>
                            <span className="text-[32px] font-bold text-[#EBEBEB]">
                                + {data.soul}
                            </span>
                        </div>
                    )}
                    {data?.blindbox > 0 && (
                        <div className="w-full z-20 flex items-center justify-center space-x-1">
                            <div className="w-[35px] h-[35px] rounded-full">
                                <img
                                    src={require('../../assets/images/blue_box.png')}
                                    alt=""
                                    className="w-full h-full object-contain"
                                />
                            </div>
                            <span className="text-[32px] font-bold text-[#EBEBEB]">
                                + {data.blindbox}
                            </span>
                        </div>
                    )}
                </div>
                <div className="flex items-center justify-center space-x-3">
                    <button className={`w-[150px] h-8 btn-tech-base btn-outline text-[9px] text-neutral-400 `} onClick={handleClose}>confirm</button>
                </div>
            </div>
        </div>
    );
};

export default TrainingEndPrompt;