import './App.css';
import { observer } from 'mobx-react-lite';
import Login from './components/Login';
import Home from './components/Home';
import userStore from "./store/user";
import { useEffect } from 'react';
const App = observer(() => {
  useEffect(() => {
    // Function to initialize the app
    const initializeApp = async () => {
      // Check if Chrome extension API is available
      if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
        try {
          // Retrieve stored token
          const { gaea_plugin_token } = await chrome.storage.local.get(['gaea_plugin_token']);
          if (gaea_plugin_token) {
            userStore.setToken(gaea_plugin_token);
          }
        } catch (error) {
          console.log("Error retrieving token from storage:", error);
        }

        // Listen for storage changes
        const handleStorageChange = (changes: any, areaName: string) => {
          if (areaName === 'local') {
            // Update token in userStore if it changes
            if (changes.gaea_plugin_token) {
              try {
                userStore.setToken(changes.gaea_plugin_token.newValue);
              } catch (error) {
                console.log("Error updating token in userStore:", error);
              }
            }
          }
        };

        // Add the listener for storage changes
        chrome.storage.onChanged.addListener(handleStorageChange);

        // Cleanup listener on component unmount
        return () => {
          chrome.storage.onChanged.removeListener(handleStorageChange);
        };
      }
    };

    // Call initializeApp when component mounts
    initializeApp();
  }, []);

  return (
    <div className="App">
      {userStore.state.gaea_plugin_token ? <Home /> : <Login />}
    </div>
  );
});

export default App;
